#include "stdlib/blas/ext/base/dcopy_within.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/math/base/special/abs.h"
#include <stdlib.h>

/**
* Performs an in-place copy of elements within a double-precision floating-point array.
*
* @param N        number of indexed elements
* @param target   target index
* @param x        input array
* @param strideX  stride length
* @param start    source start index
* @param end      source end index
*/
void API_SUFFIX(stdlib_strided_dcopy_within)( const CBLAS_INT N, const CBLAS_INT target, double *x, const CBLAS_INT strideX, const CBLAS_INT start, const CBLAS_INT end ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	API_SUFFIX(stdlib_strided_dcopy_within_ndarray)( N, target, x, strideX, ox, start, end );
}

/**
* Performs an in-place copy of elements within a double-precision floating-point array using alternative indexing semantics.
*
* @param N        number of indexed elements
* @param target   target index
* @param x        input array
* @param strideX  stride length
* @param offsetX  starting index
* @param start    source start index
* @param end      source end index
*/
void API_SUFFIX(stdlib_strided_dcopy_within_ndarray)( const CBLAS_INT N, const CBLAS_INT target, double *x, const CBLAS_INT strideX, const CBLAS_INT offsetX, const CBLAS_INT start, const CBLAS_INT end ) {
	CBLAS_INT targetIdx;
	double *tmp;
	CBLAS_INT cl;
	CBLAS_INT o;
	CBLAS_INT i;

	if ( N <= 0 ) {
		return;
	}

	// Resolve copy length:
	if ( stdlib_base_abs( end - start ) < N ) {
		cl = stdlib_base_abs( end - start );
	} else {
		cl = N;
	}

	// Allocate temporary array and extract source elements:
	tmp = (double *)malloc( cl * sizeof(double) );
	if ( tmp == NULL ) {
		return;
	}

	// Calculate source offset based on stride direction:
	if ( strideX > 0 ) {
		o = offsetX + ( start * strideX );
	} else {
		o = start;
	}

	// Copy source elements to temporary array:
	for ( i = 0; i < cl; i++ ) {
		tmp[ i ] = x[ o ];
		o += strideX;
	}

	// Resolve the target index:
	if ( strideX > 0 ) {
		targetIdx = offsetX + ( target * strideX );
	} else {
		targetIdx = target;
	}

	// Allocate elements to target position:
	for ( i = 0; i < cl; i++ ) {
		x[ targetIdx ] = tmp[ i ];
		targetIdx += strideX;
	}

	// Clean up memory:
	free( tmp );
}
